#include <string>

class Solution {
public:
    int minInsertions(std::string s) {
        int insertions = 0, openCnt = 0;
        int i = 0, n = s.size();
        while (i < n) {
            if (s[i] == '(') {
                openCnt++;
                i++;
            } else {
                if (i + 1 < n && s[i + 1] == ')') {
                    i += 2;
                } else {
                    insertions++;
                    i++;
                }
                if (openCnt > 0) openCnt--;
                else insertions++;
            }
        }
        return insertions + openCnt * 2;
    }
};

